import type { RouteRecord } from '@proteus-vue/router/types'
import type { AppScreenSpec } from '@proteus-vue/router/app-stack'

// ─── ① 全端页面清单（Web/MP：createRouter(routes)）───
export const routes: RouteRecord[] = [
  { name: "index", path: "pages/index", component: "../pages/index.vue", meta: {"title":"Proteus 超级应用","isTab":true} },
  { name: "messages", path: "pages/messages", component: "../pages/messages.vue", parent: "index", meta: {"title":"消息","isTab":true} },
  { name: "mine", path: "pages/mine", component: "../pages/mine.vue", parent: "index", meta: {"title":"我的","isTab":true} },
  { name: "verify", path: "pages/verify", component: "../pages/verify.vue", parent: "index", meta: {"title":"验收控制台"} },
]

export const tabRoutes: RouteRecord[] = routes.filter(r => r.meta?.isTab)
export const routeMap: Record<string, RouteRecord> = routes.reduce((m, r) => { m[r.name] = r; return m }, {} as Record<string, RouteRecord>)

